"""
panel_window.py — top-level Adw.ApplicationWindow.

Layout:
  Adw.NavigationSplitView
    ├── Sidebar  — VM list with status badges
    └── Content  — VM detail view for the selected domain
"""

import gi
gi.require_version("Gtk", "4.0")
gi.require_version("Adw", "1")

from gi.repository import Gtk, Adw, GLib

from .backend.libvirt_manager import LibvirtManager, DomainInfo
from .views.vm_list_view import VMListView
from .views.vm_detail_view import VMDetailView
from .views.empty_view import EmptyView


class PanelWindow(Adw.ApplicationWindow):
    def __init__(self, **kwargs):
        super().__init__(**kwargs)

        self.set_title("BulwarkOS")
        self.set_default_size(960, 620)
        self.set_size_request(720, 480)

        # ── Libvirt manager ───────────────────────────────────────────────
        self._mgr = LibvirtManager(on_domains_changed=self._on_domains_changed)

        # ── Navigation split view (sidebar + content) ─────────────────────
        self._split = Adw.NavigationSplitView()
        self._split.set_min_sidebar_width(240)
        self._split.set_max_sidebar_width(300)
        self._split.set_sidebar_width_fraction(0.28)

        # Sidebar page
        self._list_view = VMListView(
            on_select=self._on_vm_selected,
            manager=self._mgr,
            on_open_config=self._on_open_config_for,
            on_open_xml=self._on_open_xml_for,
        )
        sidebar_page = Adw.NavigationPage(title="BulwarkOS", tag="sidebar")
        sidebar_page.set_child(self._list_view)
        self._split.set_sidebar(sidebar_page)

        # Content page — starts empty
        self._empty_view   = EmptyView()
        self._detail_view  = VMDetailView(manager=self._mgr)
        self._content_page = Adw.NavigationPage(title="VM", tag="content")
        self._content_page.set_child(self._empty_view)
        self._split.set_content(self._content_page)

        # ── Toolbar view wrapping the split ──────────────────────────────
        toolbar = Adw.ToolbarView()
        toolbar.set_content(self._split)
        self.set_content(toolbar)

        # ── Keyboard shortcuts ────────────────────────────────────────────
        self._setup_shortcuts()

        # ── Start libvirt connection ──────────────────────────────────────
        # Defer slightly so the window is visible before blocking on connect
        GLib.timeout_add(100, self._start_manager)

        self.connect("close-request", self._on_close)

    # ------------------------------------------------------------------ #
    # Lifecycle                                                            #
    # ------------------------------------------------------------------ #

    def _start_manager(self):
        self._mgr.start()
        return GLib.SOURCE_REMOVE

    def _on_close(self, _win):
        self._mgr.stop()
        return False  # allow close to proceed

    # ------------------------------------------------------------------ #
    # Domain list updates (called on GTK main thread via idle_add)         #
    # ------------------------------------------------------------------ #

    def _on_domains_changed(self, domains: list[DomainInfo]):
        self._list_view.update(domains)

        # Refresh detail view if the currently selected VM's state changed
        selected = self._list_view.selected_name
        if selected:
            for d in domains:
                if d.name == selected:
                    self._detail_view.refresh(d)
                    break

    # ------------------------------------------------------------------ #
    # VM selection                                                         #
    # ------------------------------------------------------------------ #

    def _on_vm_selected(self, domain_info: DomainInfo):
        self._detail_view.load(domain_info)
        self._content_page.set_title(domain_info.meta.get("label", domain_info.name))
        self._content_page.set_child(self._detail_view)
        # On narrow screens, show content pane
        self._split.set_show_content(True)

    def _on_open_config_for(self, info: DomainInfo):
        """Open the config dialog for a VM — callable from the context menu."""
        from .views.vm_config_dialog import VMConfigDialog
        # Also navigate to that VM in the detail pane
        self._on_vm_selected(info)
        VMConfigDialog(manager=self._mgr, info=info).present(self)

    def _on_open_xml_for(self, info: DomainInfo):
        """Open the XML editor for a VM — callable from the context menu."""
        from .views.vm_xml_dialog import VMXmlDialog
        self._on_vm_selected(info)
        VMXmlDialog(manager=self._mgr, info=info).present(self)

    # ------------------------------------------------------------------ #
    # Shortcuts                                                            #
    # ------------------------------------------------------------------ #

    def _setup_shortcuts(self):
        ctrl = Gtk.ShortcutController()
        ctrl.set_scope(Gtk.ShortcutScope.GLOBAL)

        # Escape — go back to sidebar on narrow layouts
        esc = Gtk.Shortcut(
            trigger=Gtk.KeyvalTrigger.new(
                ord('\033'), 0  # GDK_KEY_Escape, no modifiers
            ),
            action=Gtk.CallbackAction.new(
                lambda *_: self._split.set_show_content(False) or True
            ),
        )
        ctrl.add_shortcut(esc)
        self.add_controller(ctrl)
